// 過去7日間の日付を計算
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const dateStr = sevenDaysAgo.toISOString().split('T')[0];
const today = now.toISOString().split('T')[0];

return [{
  json: {
    searchDate: dateStr,
    todayDate: today,
    searchQuery: `topic:ai OR topic:llm OR topic:claude OR topic:openai OR topic:gpt OR topic:gemini stars:>50 created:>${dateStr}`,
    reportDate: now.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Tokyo' })
  }
}];

// GitHubレスポンスから上位5件のリポジトリを整形
const items = $input.all();
const repos = items[0].json.items || [];
const reportDate = $('検索パラメータ設定').first().json.reportDate;

if (repos.length === 0) {
  return [{ json: { skip: true, reason: 'No repos found' } }];
}

// 上位5件を選択
const top5 = repos.slice(0, 5);

return top5.map((repo, index) => ({
  json: {
    rank: index + 1,
    name: repo.full_name,
    description: repo.description || '説明なし',
    stars: repo.stargazers_count,
    language: repo.language || '不明',
    url: repo.html_url,
    topics: (repo.topics || []).join(', '),
    created_at: repo.created_at,
    updated_at: repo.updated_at,
    forks: repo.forks_count,
    open_issues: repo.open_issues_count,
    reportDate: reportDate
  }
}));

// Claude APIレスポンスを整形してWordPress投稿用データを作成
const claudeResponse = $json.content[0].text;
const repoData = $('上位5件を整形').first().json;

// 現在アイテムのデータを取得
const currentItem = $input.item.json;
const rank = currentItem.rank || 1;
const repoName = currentItem.name || '';

// タイトル生成（SEO最適化）
const shortName = repoName.split('/').pop();
const title = `【AIツール】${shortName} - 注目のAIリポジトリ第${rank}位 | GitHubトレンド`;

// タグ生成
const tags = ['GitHubトレンド', 'AIツール', 'AI情報', currentItem.language].filter(Boolean);

return [{
  json: {
    title: title,
    content: claudeResponse,
    status: 'draft',
    categories: ['GitHubトレンド'],
    tags: tags,
    meta: {
      description: `${shortName}の使い方・特徴・対象ユーザーを詳しく解説。スター数${currentItem.stars}の注目AIリポジトリ。`,
      rank: rank,
      repoUrl: currentItem.url,
      stars: currentItem.stars
    }
  }
}];
